const problems = [{"id": 1, "title": "Ascending Sort", "difficulty": "Beginner", "description": "Given N integers, print them in nondecreasing order.", "group": "Sorting", "input": "The first line contains N. The second line contains N integers.", "output": "Print the sorted sequence on one line.", "constraints": "1 <= N <= 100000; -10^9 <= A[i] <= 10^9", "sampleInput": "5\n4 1 7 2 3", "sampleOutput": "1 2 3 4 7"}, {"id": 2, "title": "Distinct Values in Descending Order", "difficulty": "Beginner", "description": "Given a sequence of integers, remove duplicate values and print the remaining values in strictly decreasing order.", "group": "Sorting", "input": "The first line contains N. The second line contains N integers.", "output": "Print all distinct values in decreasing order.", "constraints": "1 <= N <= 200000", "sampleInput": "8\n3 1 5 3 5 7 1 2", "sampleOutput": "7 5 3 2 1"}, {"id": 3, "title": "Sort by Absolute Value", "difficulty": "Beginner", "description": "Sort the numbers by increasing absolute value. If two numbers have the same absolute value, the smaller numeric value must appear first.", "group": "Sorting", "input": "The first line contains N. The second line contains N integers.", "output": "Print the reordered sequence.", "constraints": "1 <= N <= 100000; -10^9 <= A[i] <= 10^9", "sampleInput": "6\n-5 3 -3 2 -2 7", "sampleOutput": "-2 2 -3 3 -5 7"}, {"id": 4, "title": "Student Ranking", "difficulty": "Beginner", "description": "Each student has a name and a score. Sort students by decreasing score; if two students have the same score, sort them by name in lexicographic order.", "group": "Sorting", "input": "The first line contains N. Each of the next N lines contains a name and an integer score. Names contain no spaces.", "output": "Print the sorted students, one per line, in the same format.", "constraints": "1 <= N <= 100000; 0 <= score <= 100", "sampleInput": "4\nLiam 90\nEmma 95\nNoah 90\nAva 95", "sampleOutput": "Ava 95\nEmma 95\nLiam 90\nNoah 90"}, {"id": 5, "title": "K-th Largest Distinct Number", "difficulty": "Intermediate", "description": "Find the K-th largest distinct value in the sequence. If there are fewer than K distinct values, print -1.", "group": "Sorting", "input": "The first line contains N and K. The second line contains N integers.", "output": "Print the K-th largest distinct value, or -1.", "constraints": "1 <= N <= 200000; 1 <= K <= N", "sampleInput": "7 3\n9 4 9 7 2 7 5", "sampleOutput": "5"}, {"id": 6, "title": "Minimum Distance on a Number Line", "difficulty": "Intermediate", "description": "N points lie on a number line. Find the minimum absolute distance between any two points at different positions.", "group": "Sorting", "input": "The first line contains N. The second line contains N integer coordinates.", "output": "Print the minimum positive distance. If all coordinates are identical, print 0.", "constraints": "2 <= N <= 200000; |x[i]| <= 10^9", "sampleInput": "5\n1 9 3 15 8", "sampleOutput": "1"}, {"id": 7, "title": "Largest Concatenated Number", "difficulty": "Advanced", "description": "Reorder N nonnegative integers so that concatenating their decimal representations produces the numerically largest possible result.", "group": "Sorting", "input": "The first line contains N. The second line contains N nonnegative integers.", "output": "Print the largest concatenated number without extra spaces.", "constraints": "1 <= N <= 100000; 0 <= A[i] <= 10^9", "sampleInput": "5\n3 30 34 5 9", "sampleOutput": "9534330", "note": "If every value is 0, print a single 0."}, {"id": 8, "title": "Membership Queries", "difficulty": "Beginner", "description": "A sorted array is given together with Q queries. For each query X, determine whether X appears in the array.", "group": "Searching", "input": "The first line contains N and Q. The second line contains N sorted integers. Each of the next Q lines contains X.", "output": "For each query, print YES if X exists; otherwise print NO.", "constraints": "1 <= N,Q <= 200000", "sampleInput": "5 3\n1 3 5 7 9\n5\n4\n9", "sampleOutput": "YES\nNO\nYES", "note": "Use binary search."}, {"id": 9, "title": "First Occurrence", "difficulty": "Beginner", "description": "In a nondecreasing array, find the first 1-based position of X.", "group": "Searching", "input": "The first line contains N and X. The second line contains the sorted array.", "output": "Print the first position of X, or -1 if it does not exist.", "constraints": "1 <= N <= 200000", "sampleInput": "6 2\n1 2 2 2 5 8", "sampleOutput": "2"}, {"id": 10, "title": "Last Occurrence", "difficulty": "Beginner", "description": "In a nondecreasing array, find the last 1-based position of X.", "group": "Searching", "input": "The first line contains N and X. The second line contains the sorted array.", "output": "Print the last position of X, or -1 if it does not exist.", "constraints": "1 <= N <= 200000", "sampleInput": "6 2\n1 2 2 2 5 8", "sampleOutput": "4"}, {"id": 11, "title": "Frequency in a Sorted Array", "difficulty": "Intermediate", "description": "Count how many times X occurs in a sorted array without scanning the entire array.", "group": "Searching", "input": "The first line contains N and X. The second line contains N sorted integers.", "output": "Print the number of occurrences of X.", "constraints": "1 <= N <= 200000", "sampleInput": "7 5\n1 2 2 2 5 5 7", "sampleOutput": "2", "note": "A lower-bound / upper-bound approach gives O(log N) query time."}, {"id": 12, "title": "Closest Value", "difficulty": "Intermediate", "description": "Given a sorted array and a target X, find the value whose absolute difference from X is minimum. If two values are equally close, choose the smaller value.", "group": "Searching", "input": "The first line contains N and X. The second line contains N sorted integers.", "output": "Print the chosen value.", "constraints": "1 <= N <= 200000", "sampleInput": "5 6\n1 4 8 12 20", "sampleOutput": "4"}, {"id": 13, "title": "Integer Square Root", "difficulty": "Intermediate", "description": "Given a nonnegative integer N, compute floor(sqrt(N)) without using a built-in square-root function.", "group": "Searching", "input": "One line contains N.", "output": "Print floor(sqrt(N)).", "constraints": "0 <= N <= 10^18", "sampleInput": "27", "sampleOutput": "5", "note": "Avoid overflow when checking mid * mid."}, {"id": 14, "title": "Equal Cake Pieces", "difficulty": "Advanced", "description": "There are N cakes with integer lengths. Each cake may be cut into smaller integer-length pieces. Find the largest positive integer length L such that at least K equal pieces of length L can be produced.", "group": "Searching", "input": "The first line contains N and K. The second line contains N cake lengths.", "output": "Print the maximum feasible L.", "constraints": "1 <= N <= 200000; 1 <= K <= 10^18; 1 <= A[i] <= 10^18", "sampleInput": "3 5\n10 15 20", "sampleOutput": "7", "note": "This is a binary-search-on-the-answer problem."}, {"id": 15, "title": "Polynomial Evaluation", "difficulty": "Beginner", "description": "Evaluate a polynomial P(x) = a[n]x^n + ... + a[1]x + a[0] efficiently.", "group": "Numerical Methods", "input": "The first line contains n and x. The second line contains n+1 coefficients from a[n] to a[0].", "output": "Print P(x).", "constraints": "0 <= n <= 10^6; coefficient and x values fit in signed 64-bit arithmetic for all intermediate results.", "sampleInput": "3 2\n1 0 -2 5", "sampleOutput": "9", "note": "Use Horner's method to achieve O(n) time."}, {"id": 16, "title": "Root of a Cubic Equation", "difficulty": "Intermediate", "description": "Find the real root of f(x) = x^3 + x - 10 in the interval [0, 3].", "group": "Numerical Methods", "input": "There is no input.", "output": "Print the root rounded to 6 digits after the decimal point.", "constraints": "Absolute error must not exceed 10^-6.", "note": "A monotonic function on a known interval can be solved by binary search."}, {"id": 17, "title": "Numerical Integration", "difficulty": "Intermediate", "description": "Approximate the integral of f(x) = x^2 + 2x + 1 over [a,b] using the midpoint rule with exactly N equal subintervals.", "group": "Numerical Methods", "input": "One line contains real numbers a and b and integer N.", "output": "Print the approximation with at least 6 digits after the decimal point.", "constraints": "-10^4 <= a < b <= 10^4; 1 <= N <= 10^7", "sampleInput": "0 2 100000", "sampleOutput": "8.666667"}, {"id": 18, "title": "Square Root by Newton's Method", "difficulty": "Intermediate", "description": "Approximate sqrt(N) using Newton-Raphson iteration. Start with x0 = max(1,N). Stop when two consecutive estimates differ by less than 10^-10.", "group": "Numerical Methods", "input": "One line contains real number N.", "output": "Print the final estimate with 10 digits after the decimal point.", "constraints": "0 <= N <= 10^12", "sampleInput": "2", "sampleOutput": "1.4142135624"}, {"id": 19, "title": "Monotonic Equation Solver", "difficulty": "Advanced", "description": "Given K, find the unique nonnegative real x satisfying x^5 + 3x^3 + x = K.", "group": "Numerical Methods", "input": "One line contains K.", "output": "Print x with absolute error at most 10^-6.", "constraints": "0 <= K <= 10^18", "sampleInput": "5", "sampleOutput": "1.000000", "note": "The left-hand side is strictly increasing for x >= 0."}, {"id": 20, "title": "Fibonacci Modulo", "difficulty": "Beginner", "description": "Compute the N-th Fibonacci number where F1 = 1, F2 = 1 and Fn = F(n-1) + F(n-2).", "group": "Dynamic Programming", "input": "One line contains N.", "output": "Print F(N) modulo 1000000007.", "constraints": "1 <= N <= 10^6", "sampleInput": "10", "sampleOutput": "55"}, {"id": 21, "title": "Climbing Stairs", "difficulty": "Beginner", "description": "A staircase has N steps. At each move you may climb either 1 or 2 steps. Count the number of distinct ways to reach exactly step N.", "group": "Dynamic Programming", "input": "One line contains N.", "output": "Print the number of ways modulo 1000000007.", "constraints": "0 <= N <= 10^6", "sampleInput": "4", "sampleOutput": "5"}, {"id": 22, "title": "Climbing Stairs with Three Moves", "difficulty": "Beginner", "description": "A staircase has N steps. Each move may advance 1, 2, or 3 steps. Count the number of distinct ways to reach exactly step N.", "group": "Dynamic Programming", "input": "One line contains N.", "output": "Print the number of ways modulo 1000000007.", "constraints": "0 <= N <= 10^6", "sampleInput": "4", "sampleOutput": "7"}, {"id": 23, "title": "Maximum Non-Adjacent Sum", "difficulty": "Intermediate", "description": "Choose a subset of array elements such that no two chosen elements are adjacent. Maximize the sum. Choosing no element is allowed.", "group": "Dynamic Programming", "input": "The first line contains N. The second line contains N integers.", "output": "Print the maximum possible sum.", "constraints": "1 <= N <= 200000; -10^9 <= A[i] <= 10^9", "sampleInput": "5\n5 1 2 10 6", "sampleOutput": "17"}, {"id": 24, "title": "Minimum Coin Change", "difficulty": "Intermediate", "description": "Given coin denominations and a target amount S, find the minimum number of coins needed to make exactly S. Each denomination may be used any number of times.", "group": "Dynamic Programming", "input": "The first line contains M and S. The second line contains M positive coin denominations.", "output": "Print the minimum number of coins, or -1 if S cannot be formed.", "constraints": "1 <= M <= 100; 0 <= S <= 100000", "sampleInput": "3 6\n1 3 4", "sampleOutput": "2"}, {"id": 25, "title": "0/1 Knapsack", "difficulty": "Intermediate", "description": "There are N items. Item i has weight w[i] and value v[i]. Choose each item at most once so that total weight does not exceed W and total value is maximized.", "group": "Dynamic Programming", "input": "The first line contains N and W. Each of the next N lines contains weight and value.", "output": "Print the maximum total value.", "constraints": "1 <= N <= 200; 0 <= W <= 200000", "sampleInput": "4 7\n6 13\n4 8\n3 6\n5 12", "sampleOutput": "14"}, {"id": 26, "title": "Longest Increasing Subsequence", "difficulty": "Intermediate", "description": "Find the length of the longest strictly increasing subsequence.", "group": "Dynamic Programming", "input": "The first line contains N. The second line contains N integers.", "output": "Print the LIS length.", "constraints": "1 <= N <= 200000", "sampleInput": "8\n10 9 2 5 3 7 101 18", "sampleOutput": "4", "note": "First solve in O(N^2), then improve to O(N log N)."}, {"id": 27, "title": "Longest Common Subsequence", "difficulty": "Advanced", "description": "Given two strings, find the length of their longest common subsequence.", "group": "Dynamic Programming", "input": "The first line contains string A. The second line contains string B.", "output": "Print the LCS length.", "constraints": "1 <= |A|,|B| <= 3000", "sampleInput": "ABCBDAB\nBDCABA", "sampleOutput": "4"}, {"id": 28, "title": "Maximum-Score Grid Path", "difficulty": "Intermediate", "description": "An N by M grid contains integer rewards. Start at (1,1) and reach (N,M), moving only right or down. Maximize the sum of visited cell values.", "group": "Dynamic Programming", "input": "The first line contains N and M. The next N lines contain M integers each.", "output": "Print the maximum obtainable score.", "constraints": "1 <= N,M <= 2000; |value| <= 10^6", "sampleInput": "3 3\n5 1 2\n4 10 1\n1 1 20", "sampleOutput": "40"}, {"id": 29, "title": "Grid Paths with Obstacles", "difficulty": "Advanced", "description": "An N by M grid contains free cells (.) and blocked cells (#). Starting at the top-left cell, count the number of ways to reach the bottom-right cell using only right and down moves.", "group": "Dynamic Programming", "input": "The first line contains N and M. The next N lines contain the grid.", "output": "Print the number of valid paths modulo 1000000007.", "constraints": "1 <= N,M <= 2000", "sampleInput": "3 4\n....\n.#..\n....", "sampleOutput": "4"}, {"id": 30, "title": "Count Reachable Tree Nodes", "difficulty": "Beginner", "description": "You are given an undirected tree description and a start node S. Count how many distinct nodes are reachable from S.", "group": "Trees", "input": "The first line contains N and S. The next N-1 lines contain tree edges u v.", "output": "Print the number of reachable nodes.", "constraints": "1 <= N <= 200000", "sampleInput": "5 3\n1 2\n1 3\n3 4\n3 5", "sampleOutput": "5", "note": "For a valid tree, the answer is N; this problem is mainly for DFS/BFS implementation practice."}, {"id": 31, "title": "Depth of Every Node", "difficulty": "Beginner", "description": "A tree is rooted at node 1. Compute the depth of every node, where depth(1)=0.", "group": "Trees", "input": "The first line contains N. The next N-1 lines contain edges.", "output": "Print N integers: depth[1] through depth[N].", "constraints": "1 <= N <= 200000", "sampleInput": "5\n1 2\n1 3\n2 4\n2 5", "sampleOutput": "0 1 1 2 2"}, {"id": 32, "title": "Count Leaf Nodes", "difficulty": "Beginner", "description": "A tree is rooted at node 1. Count the number of leaf nodes. For N=1, the root is also considered a leaf.", "group": "Trees", "input": "The first line contains N. The next N-1 lines contain edges.", "output": "Print the number of leaves.", "constraints": "1 <= N <= 200000", "sampleInput": "5\n1 2\n1 3\n2 4\n2 5", "sampleOutput": "3"}, {"id": 33, "title": "Subtree Sizes", "difficulty": "Intermediate", "description": "A tree is rooted at node 1. For each node u, compute the number of nodes in the subtree rooted at u, including u itself.", "group": "Trees", "input": "The first line contains N. The next N-1 lines contain edges.", "output": "Print N integers: subtree_size[1] through subtree_size[N].", "constraints": "1 <= N <= 200000", "sampleInput": "5\n1 2\n1 3\n2 4\n2 5", "sampleOutput": "5 3 1 1 1"}, {"id": 34, "title": "Tree Diameter", "difficulty": "Advanced", "description": "Find the maximum number of edges on a simple path between any two nodes of a tree.", "group": "Trees", "input": "The first line contains N. The next N-1 lines contain edges.", "output": "Print the tree diameter in number of edges.", "constraints": "1 <= N <= 200000", "sampleInput": "6\n1 2\n2 3\n2 4\n4 5\n5 6", "sampleOutput": "4", "note": "A standard solution uses two BFS/DFS traversals."}, {"id": 35, "title": "Lowest Common Ancestor Queries", "difficulty": "Advanced", "description": "A tree is rooted at node 1. For each query (u,v), return their lowest common ancestor.", "group": "Trees", "input": "The first line contains N and Q. The next N-1 lines contain edges. The next Q lines contain u and v.", "output": "Print one LCA per query.", "constraints": "1 <= N,Q <= 200000", "sampleInput": "7 3\n1 2\n1 3\n2 4\n2 5\n3 6\n3 7\n4 5\n4 6\n6 7", "sampleOutput": "2\n1\n3", "note": "Use binary lifting or another O((N+Q) log N) method."}, {"id": 36, "title": "Reachable Vertices", "difficulty": "Beginner", "description": "Given an undirected graph and a start vertex 1, count how many vertices are reachable from 1.", "group": "Graph Theory", "input": "The first line contains N and M. The next M lines contain undirected edges.", "output": "Print the number of reachable vertices.", "constraints": "1 <= N,M <= 200000", "sampleInput": "6 4\n1 2\n2 3\n4 5\n5 6", "sampleOutput": "3"}, {"id": 37, "title": "Connected Components", "difficulty": "Beginner", "description": "Count the number of connected components in an undirected graph.", "group": "Graph Theory", "input": "The first line contains N and M. The next M lines contain undirected edges.", "output": "Print the number of connected components.", "constraints": "1 <= N,M <= 200000", "sampleInput": "6 3\n1 2\n2 3\n5 6", "sampleOutput": "3"}, {"id": 38, "title": "Shortest Path in an Unweighted Graph", "difficulty": "Intermediate", "description": "Find the minimum number of edges on a path from S to T in an unweighted undirected graph.", "group": "Graph Theory", "input": "The first line contains N M S T. The next M lines contain edges.", "output": "Print the minimum number of edges, or -1 if T is unreachable.", "constraints": "1 <= N,M <= 200000", "sampleInput": "5 5 1 5\n1 2\n2 5\n1 3\n3 4\n4 5", "sampleOutput": "2", "note": "Use BFS."}, {"id": 39, "title": "Maze Escape", "difficulty": "Intermediate", "description": "A rectangular maze contains S (start), E (exit), . (free cell), and # (wall). You may move up, down, left, or right. Find the minimum number of moves from S to E.", "group": "Graph Theory", "input": "The first line contains N and M. The next N lines contain the maze.", "output": "Print the minimum number of moves, or -1 if impossible.", "constraints": "1 <= N,M <= 2000", "sampleInput": "5 5\nS....\n.###.\n...#.\n.#...\n....E", "sampleOutput": "8"}, {"id": 40, "title": "Dijkstra: One Destination", "difficulty": "Advanced", "description": "A directed graph has nonnegative edge weights. Find the shortest distance from S to T.", "group": "Graph Theory", "input": "The first line contains N M S T. The next M lines contain u v w.", "output": "Print the shortest distance, or -1 if T is unreachable.", "constraints": "1 <= N,M <= 200000; 0 <= w <= 10^9", "sampleInput": "5 6 1 5\n1 2 4\n1 3 2\n3 2 1\n2 5 5\n3 4 7\n4 5 1", "sampleOutput": "8"}, {"id": 41, "title": "Dijkstra: All Destinations", "difficulty": "Advanced", "description": "A directed graph has nonnegative edge weights. Compute the shortest distance from source S to every vertex.", "group": "Graph Theory", "input": "The first line contains N M S. The next M lines contain u v w.", "output": "Print N values. Use -1 for unreachable vertices.", "constraints": "1 <= N,M <= 200000; 0 <= w <= 10^9", "sampleInput": "4 4 1\n1 2 5\n1 3 2\n3 2 1\n2 4 4", "sampleOutput": "0 3 2 7"}, {"id": 42, "title": "All-Pairs Shortest Paths", "difficulty": "Advanced", "description": "Given a directed weighted graph, answer Q shortest-path queries between arbitrary pairs. Edge weights may be negative, but there are no negative cycles.", "group": "Graph Theory", "input": "The first line contains N M Q. The next M lines contain u v w. The next Q lines contain s t.", "output": "For each query, print the shortest distance or INF if no path exists.", "constraints": "1 <= N <= 500; 0 <= M <= N(N-1); |w| <= 10^9", "sampleInput": "3 3 2\n1 2 4\n2 3 -1\n1 3 10\n1 3\n3 1", "sampleOutput": "3\nINF", "note": "Use Floyd-Warshall."}, {"id": 43, "title": "Topological Ordering", "difficulty": "Advanced", "description": "A directed graph represents prerequisite relations. Output any topological ordering if one exists.", "group": "Graph Theory", "input": "The first line contains N and M. The next M lines contain directed edges u v meaning u must come before v.", "output": "Print a valid ordering of all N vertices, or IMPOSSIBLE if the graph contains a cycle.", "constraints": "1 <= N,M <= 200000", "sampleInput": "4 3\n1 2\n2 3\n1 4", "sampleOutput": "1 2 4 3", "note": "Any valid topological order is accepted."}, {"id": 44, "title": "Cycle Detection", "difficulty": "Advanced", "description": "Determine whether a graph contains a cycle. Solve two modes: U for undirected graphs and D for directed graphs.", "group": "Graph Theory", "input": "The first line contains a character mode, then N and M. The next M lines contain edges.", "output": "Print CYCLE or ACYCLIC.", "constraints": "1 <= N,M <= 200000", "sampleInput": "D 3 3\n1 2\n2 3\n3 1", "sampleOutput": "CYCLE"}, {"id": 45, "title": "Minimum Spanning Tree", "difficulty": "Advanced", "description": "Given a connected undirected weighted graph, find the minimum possible total weight of a spanning tree.", "group": "Graph Theory", "input": "The first line contains N and M. The next M lines contain u v w.", "output": "Print the total weight of a minimum spanning tree.", "constraints": "1 <= N,M <= 200000; -10^9 <= w <= 10^9", "sampleInput": "4 5\n1 2 1\n1 3 4\n2 3 2\n2 4 5\n3 4 3", "sampleOutput": "6", "note": "Use Kruskal or Prim."}, {"id": 46, "title": "Prime Test", "difficulty": "Beginner", "description": "Determine whether N is prime.", "group": "Number Theory", "input": "One line contains N.", "output": "Print PRIME or COMPOSITE. For N < 2, print COMPOSITE.", "constraints": "0 <= N <= 10^12", "sampleInput": "97", "sampleOutput": "PRIME"}, {"id": 47, "title": "List All Primes", "difficulty": "Intermediate", "description": "Print all prime numbers from 2 through N in increasing order.", "group": "Number Theory", "input": "One line contains N.", "output": "Print the primes separated by spaces. Print an empty line if there are none.", "constraints": "1 <= N <= 10^7", "sampleInput": "20", "sampleOutput": "2 3 5 7 11 13 17 19", "note": "Use the Sieve of Eratosthenes."}, {"id": 48, "title": "Greatest Common Divisor", "difficulty": "Beginner", "description": "Compute gcd(a,b).", "group": "Number Theory", "input": "One line contains integers a and b.", "output": "Print gcd(|a|,|b|).", "constraints": "|a|,|b| <= 10^18; not both zero", "sampleInput": "48 18", "sampleOutput": "6"}, {"id": 49, "title": "Least Common Multiple", "difficulty": "Beginner", "description": "Compute lcm(a,b).", "group": "Number Theory", "input": "One line contains nonnegative integers a and b.", "output": "Print lcm(a,b). If either number is 0, print 0.", "constraints": "0 <= a,b <= 10^18; answer fits signed 64-bit integer", "sampleInput": "12 18", "sampleOutput": "36", "note": "Reduce overflow risk by dividing by gcd before multiplying."}, {"id": 50, "title": "Prime Factorization", "difficulty": "Intermediate", "description": "Factorize N into prime powers.", "group": "Number Theory", "input": "One line contains N.", "output": "Print factors in increasing prime order using the format p^e separated by spaces. For N=1, print 1.", "constraints": "1 <= N <= 10^12", "sampleInput": "360", "sampleOutput": "2^3 3^2 5^1"}, {"id": 51, "title": "Fast Modular Exponentiation", "difficulty": "Intermediate", "description": "Compute a^b mod m efficiently.", "group": "Number Theory", "input": "One line contains a, b, and m.", "output": "Print a^b mod m.", "constraints": "0 <= a <= 10^18; 0 <= b <= 10^18; 1 <= m <= 10^18", "sampleInput": "2 10 1000", "sampleOutput": "24", "note": "Use binary exponentiation."}, {"id": 52, "title": "Huge Fibonacci Index", "difficulty": "Advanced", "description": "Compute F(N) modulo 1000000007 for N up to 10^18, with F0=0 and F1=1.", "group": "Number Theory", "input": "One line contains N.", "output": "Print F(N) modulo 1000000007.", "constraints": "0 <= N <= 10^18", "sampleInput": "100", "sampleOutput": "687995182", "note": "Use fast doubling or matrix exponentiation."}, {"id": 53, "title": "Modular Inverse", "difficulty": "Advanced", "description": "Given integers a and prime p where a is not divisible by p, find x such that a*x = 1 (mod p).", "group": "Number Theory", "input": "One line contains a and p.", "output": "Print the unique x in [1,p-1].", "constraints": "2 <= p <= 10^9+7 and p is prime; 1 <= a < p", "sampleInput": "3 11", "sampleOutput": "4", "note": "Fermat's little theorem gives a^(p-2) mod p."}, {"id": 54, "title": "Distance Between Two Points", "difficulty": "Beginner", "description": "Compute the Euclidean distance between two points in the plane.", "group": "Geometry", "input": "One line contains x1 y1 x2 y2 as real numbers.", "output": "Print the distance with 6 digits after the decimal point.", "constraints": "|coordinate| <= 10^9", "sampleInput": "0 0 3 4", "sampleOutput": "5.000000"}, {"id": 55, "title": "Triangle Area", "difficulty": "Beginner", "description": "Given three planar points, compute the area of the triangle they form.", "group": "Geometry", "input": "Three lines follow, each containing x y.", "output": "Print the area with 6 digits after the decimal point.", "constraints": "|coordinate| <= 10^9", "sampleInput": "0 0\n4 0\n0 3", "sampleOutput": "6.000000"}, {"id": 56, "title": "Collinearity Test", "difficulty": "Beginner", "description": "Determine whether three points are collinear.", "group": "Geometry", "input": "Three lines follow, each containing integer coordinates x y.", "output": "Print YES if the points are collinear; otherwise print NO.", "constraints": "|coordinate| <= 10^9", "sampleInput": "1 1\n2 2\n3 3", "sampleOutput": "YES", "note": "Use the 2D cross product; do not rely on floating-point slopes."}, {"id": 57, "title": "Left, Right, or Collinear", "difficulty": "Intermediate", "description": "Given directed segment A->B and point C, determine whether C lies to the LEFT, to the RIGHT, or COLLINEAR with the directed line.", "group": "Geometry", "input": "The input contains coordinates ax ay bx by cx cy.", "output": "Print LEFT, RIGHT, or COLLINEAR.", "constraints": "All coordinates are integers with absolute value <= 10^9", "sampleInput": "0 0 4 0 2 3", "sampleOutput": "LEFT"}, {"id": 58, "title": "Convex Hull", "difficulty": "Advanced", "description": "Given N planar points, output the vertices of their convex hull in counterclockwise order, starting from the lexicographically smallest vertex. Remove duplicate input points. Collinear points on hull edges should not appear unless they are endpoints of the edge.", "group": "Geometry", "input": "The first line contains N. The next N lines contain integer coordinates x y.", "output": "First print H, the number of hull vertices. Then print the H vertices, one per line.", "constraints": "1 <= N <= 200000; |coordinate| <= 10^9", "sampleInput": "5\n0 0\n2 0\n2 2\n0 2\n1 1", "sampleOutput": "4\n0 0\n2 0\n2 2\n0 2", "note": "Use monotonic chain or Graham scan."}, {"id": 59, "title": "Maximum Number of Activities", "difficulty": "Beginner", "description": "Each activity has a start time and an end time. Choose the maximum number of non-overlapping activities that one person can attend. An activity starting exactly when another ends is allowed.", "group": "Greedy Algorithms", "input": "The first line contains N. The next N lines contain start and end.", "output": "Print the maximum number of activities.", "constraints": "1 <= N <= 200000; start < end", "sampleInput": "5\n1 4\n3 5\n0 6\n5 7\n8 9", "sampleOutput": "3", "note": "Sort by finishing time."}, {"id": 60, "title": "Greedy Currency Change", "difficulty": "Beginner", "description": "Using banknote values 1, 5, 10, 20, 50, and 100, find the minimum number of notes needed to make exactly N.", "group": "Greedy Algorithms", "input": "One line contains N.", "output": "Print the minimum number of notes.", "constraints": "0 <= N <= 10^18", "sampleInput": "186", "sampleOutput": "5", "note": "For this canonical system, repeatedly taking the largest possible note is optimal."}, {"id": 61, "title": "Minimum Cost to Connect Ropes", "difficulty": "Intermediate", "description": "There are N ropes. Combining ropes of lengths a and b costs a+b and creates one rope of length a+b. Find the minimum total cost to combine all ropes into one.", "group": "Greedy Algorithms", "input": "The first line contains N. The second line contains N positive lengths.", "output": "Print the minimum total cost.", "constraints": "1 <= N <= 200000; length <= 10^9", "sampleInput": "4\n1 2 3 4", "sampleOutput": "19", "note": "Use a min-priority queue."}, {"id": 62, "title": "Job Sequencing with Deadlines", "difficulty": "Advanced", "description": "Each job takes exactly one unit of time and has a positive profit. Job i must finish no later than its deadline to earn its profit. Schedule jobs to maximize total profit.", "group": "Greedy Algorithms", "input": "The first line contains N. Each of the next N lines contains deadline and profit.", "output": "Print the maximum total profit.", "constraints": "1 <= N <= 200000; 1 <= deadline <= 200000; 0 <= profit <= 10^9", "sampleInput": "4\n4 20\n1 10\n1 40\n1 30", "sampleOutput": "60"}, {"id": 63, "title": "Minimum Fuel Stops on a Route", "difficulty": "Advanced", "description": "A vehicle starts at position 0 and must reach D. With a full tank it can travel at most K distance. Stations are located at given positions, and refueling instantly restores a full tank. Find the minimum number of stops needed.", "group": "Greedy Algorithms", "input": "The first line contains N, D, and K. The second line contains N station positions in increasing order.", "output": "Print the minimum number of refueling stops, or -1 if the destination cannot be reached.", "constraints": "0 <= N <= 200000; 1 <= K <= D <= 10^18", "sampleInput": "4 25 10\n7 10 14 20", "sampleOutput": "2", "note": "At each stop, go to the farthest reachable next station/destination."}, {"id": 64, "title": "Load Balancing Across Machines", "difficulty": "Advanced", "description": "N independent jobs have processing times t[i]. Assign each job to one of M identical machines. The load of a machine is the sum of its assigned processing times. Minimize the maximum machine load.", "group": "Greedy Algorithms", "input": "The first line contains N and M. The second line contains N processing times.", "output": "Print the minimum possible maximum load.", "constraints": "1 <= M <= N <= 30; 1 <= t[i] <= 10^9", "sampleInput": "5 2\n7 2 5 10 8", "sampleOutput": "17", "note": "For small N, use branch-and-bound/backtracking; for larger variants, study greedy approximation methods."}, {"id": 65, "title": "Take 1 or 2 Stones", "difficulty": "Beginner", "description": "A pile contains N stones. Two players alternate turns. On each turn, a player removes 1 or 2 stones. The player who removes the last stone wins. Determine the winner under optimal play.", "group": "Game Theory", "input": "One line contains N.", "output": "Print FIRST if the first player wins; otherwise print SECOND.", "constraints": "1 <= N <= 10^18", "sampleInput": "5", "sampleOutput": "FIRST"}, {"id": 66, "title": "Take 1, 3, or 4 Stones", "difficulty": "Intermediate", "description": "A pile contains N stones. On each turn, a player removes exactly 1, 3, or 4 stones when possible. The player taking the last stone wins. Determine the winner under optimal play.", "group": "Game Theory", "input": "One line contains N.", "output": "Print FIRST or SECOND.", "constraints": "1 <= N <= 10^6", "sampleInput": "7", "sampleOutput": "SECOND", "note": "Classify winning and losing states with DP."}, {"id": 67, "title": "Nim", "difficulty": "Intermediate", "description": "There are N piles of stones. On each turn, a player chooses one nonempty pile and removes any positive number of stones from it. The player making the last move wins. Determine the winner under optimal play.", "group": "Game Theory", "input": "The first line contains N. The second line contains the pile sizes.", "output": "Print FIRST or SECOND.", "constraints": "1 <= N <= 200000; 0 <= pile <= 10^18", "sampleInput": "3\n3 4 5", "sampleOutput": "FIRST", "note": "Use the xor of all pile sizes."}, {"id": 68, "title": "Optimal End-Picking Game", "difficulty": "Advanced", "description": "An array of N integers is on the table. Two players alternate. Each turn, a player takes either the leftmost or the rightmost remaining number and adds it to their score. Both play optimally. Find the maximum score the first player can guarantee.", "group": "Game Theory", "input": "The first line contains N. The second line contains N integers.", "output": "Print the first player's guaranteed maximum score.", "constraints": "1 <= N <= 3000; |A[i]| <= 10^9", "sampleInput": "4\n8 15 3 7", "sampleOutput": "22"}, {"id": 69, "title": "Grid Movement Game", "difficulty": "Intermediate", "description": "A token starts at cell (N,M). Players alternate moving it one step UP, LEFT, or diagonally UP-LEFT when possible. The player who moves the token into (1,1) wins immediately. Determine the winner under optimal play.", "group": "Game Theory", "input": "One line contains N and M.", "output": "Print FIRST or SECOND.", "constraints": "1 <= N,M <= 10^9", "sampleInput": "2 2", "sampleOutput": "FIRST", "note": "Look for a repeating pattern of winning and losing states."}, {"id": 70, "title": "Take 1-3 Values from the Front", "difficulty": "Advanced", "description": "A sequence of N integers is given. Two players alternate. On each turn, a player must take 1, 2, or 3 values from the front of the remaining sequence and adds their sum to their score. Both play optimally. Find the maximum possible final score difference (first player score minus second player score).", "group": "Game Theory", "input": "The first line contains N. The second line contains N integers.", "output": "Print the optimal score difference.", "constraints": "1 <= N <= 200000; |A[i]| <= 10^9", "sampleInput": "5\n1 2 3 4 5", "sampleOutput": "3", "note": "A one-dimensional DP on score difference works well."}, {"id": 71, "title": "Warehouse Robot - Shortest Route", "difficulty": "Intermediate", "description": "A warehouse is represented by a grid containing S, E, free cells (.), and obstacles (#). A robot may move in the four cardinal directions. Find the shortest number of moves from S to E.", "group": "Robotics & Optimization", "input": "The first line contains N and M. The next N lines contain the grid.", "output": "Print the minimum number of moves, or -1 if no route exists.", "constraints": "1 <= N,M <= 2000", "sampleInput": "5 6\nS..#..\n.#.#..\n.#....\n..##..\n.....E", "sampleOutput": "9", "note": "Use BFS because every move has equal cost."}, {"id": 72, "title": "Weighted Grid Robot", "difficulty": "Advanced", "description": "Each cell of an N by M grid has a nonnegative traversal cost. A robot starts at (1,1) and must reach (N,M). It may move up, down, left, or right. The total path cost is the sum of costs of all visited cells, including the start and end cells.", "group": "Robotics & Optimization", "input": "The first line contains N and M. The next N lines contain M costs.", "output": "Print the minimum possible path cost.", "constraints": "1 <= N,M <= 1000; 0 <= cost <= 10^9", "sampleInput": "4 4\n1 4 1 2\n2 9 1 3\n1 1 1 8\n5 2 1 1", "sampleOutput": "8", "note": "Treat each grid cell as a graph vertex and use Dijkstra."}, {"id": 73, "title": "Dynamic Obstacle Grid", "difficulty": "Advanced", "description": "A robot moves on an N by M grid. Time starts at 0. Each move to a neighboring free cell takes exactly 1 second. Some cells become blocked starting at specified times and remain blocked forever. The robot may wait in place for 1 second. Find the earliest arrival time at E from S.", "group": "Robotics & Optimization", "input": "The first line contains N, M, and B. The next N lines contain the base grid. The next B lines contain r c t, meaning cell (r,c) becomes blocked at time t.", "output": "Print the earliest arrival time, or -1 if impossible.", "constraints": "1 <= N,M <= 300; 0 <= B <= NM", "sampleInput": "3 4 2\nS...\n....\n...E\n2 2 2\n2 3 3", "sampleOutput": "5", "note": "A state may need position plus time, or a more compact earliest-arrival formulation."}, {"id": 74, "title": "A* Pathfinding", "difficulty": "Advanced", "description": "Implement A* search on a 4-neighbor grid with unit movement cost. Use Manhattan distance h = |r- r_goal| + |c-c_goal|. Return both the shortest-path length and the number of grid states removed from the priority queue.", "group": "Robotics & Optimization", "input": "The first line contains N and M, followed by the grid with S, E, ., and #.", "output": "Print shortest_length expanded_count. If no path exists, shortest_length is -1.", "constraints": "1 <= N,M <= 1000", "sampleInput": "4 6\nS.....\n.###..\n...#..\n.....E", "sampleOutput": "8 12", "note": "Different tie-breaking rules may change expanded_count; define your tie-breaking rule consistently in your implementation."}, {"id": 75, "title": "Line-Following Decision Logic", "difficulty": "Beginner", "description": "A three-sensor line follower reports L, C, R as bits. Exactly one or two adjacent sensors may detect the line. Produce a steering command according to this rule: 010 -> FORWARD; 100 or 110 -> LEFT; 001 or 011 -> RIGHT; 111 -> FORWARD; all other patterns -> LOST.", "group": "Robotics & Optimization", "input": "The first line contains T. Each of the next T lines contains a three-character bit string.", "output": "Print one command per line.", "constraints": "1 <= T <= 100000", "sampleInput": "5\n001\n011\n010\n110\n100", "sampleOutput": "RIGHT\nRIGHT\nFORWARD\nLEFT\nLEFT"}, {"id": 76, "title": "Proportional Controller", "difficulty": "Beginner", "description": "For each measurement, compute error = target - current and output = Kp * error. Clamp the output to the interval [-255,255].", "group": "Robotics & Optimization", "input": "The first line contains real Kp and integer T. Each of the next T lines contains target and current as real numbers.", "output": "Print each clamped output with 3 digits after the decimal point.", "constraints": "1 <= T <= 100000", "sampleInput": "2.0 3\n10 7\n10 20\n1000 0", "sampleOutput": "6.000\n-20.000\n255.000"}, {"id": 77, "title": "PID Controller Simulation", "difficulty": "Intermediate", "description": "Simulate a discrete PID controller. For time step i, error e[i] is given. Define P=Kp*e[i], I=Ki*sum(e[0..i]), and D=Kd*(e[i]-e[i-1]), with e[-1]=0. Output P+I+D for each time step.", "group": "Robotics & Optimization", "input": "The first line contains Kp Ki Kd and T. The second line contains T error values.", "output": "Print T controller outputs with 6 digits after the decimal point.", "constraints": "1 <= T <= 200000", "sampleInput": "1.0 0.5 0.25 3\n2 1 -1", "sampleOutput": "3.500000 2.750000 -0.250000"}, {"id": 78, "title": "Robot-Task Assignment", "difficulty": "Advanced", "description": "There are N tasks and M robots. Robot j has speed s[j]. Task i has work amount w[i]. If robot j performs task i alone, the processing time is w[i]/s[j]. Each task must be assigned to exactly one robot, and a robot processes its assigned tasks sequentially. Minimize the maximum robot completion time.", "group": "Robotics & Optimization", "input": "The first line contains N and M. The second line contains N work amounts. The third line contains M robot speeds.", "output": "Print the optimal maximum completion time with absolute error at most 10^-6.", "constraints": "1 <= M <= N <= 20; 1 <= w[i],s[j] <= 10^6", "sampleInput": "3 2\n10 20 30\n1 2", "sampleOutput": "30.000000", "note": "This is an exact assignment/search problem for small N; use pruning aggressively."}, {"id": 79, "title": "Server Load Balancing", "difficulty": "Advanced", "description": "N tasks with integer processing times must be assigned to M identical servers. Minimize the maximum load across all servers.", "group": "Robotics & Optimization", "input": "The first line contains N and M. The second line contains task times.", "output": "Print the optimal maximum load.", "constraints": "1 <= M <= N <= 30; 1 <= t[i] <= 10^9", "sampleInput": "6 3\n8 7 6 5 4 3", "sampleOutput": "12", "note": "Try sorting tasks descending before backtracking, and skip symmetric server states."}, {"id": 80, "title": "Mini Genetic Algorithm", "difficulty": "Advanced", "description": "Implement a simple genetic algorithm to maximize f(x) = -(x-37)^2 + 1000 for integer x in [0,100]. Use a population of 20 integers, tournament selection of size 3, one-point crossover on 7-bit binary representations with probability 0.8, bit-flip mutation with probability 0.02 per bit, and elitism preserving the best individual. Run exactly 100 generations.", "group": "Robotics & Optimization", "input": "Input contains one integer seed for the pseudo-random generator.", "output": "Print the best x found and its fitness.", "constraints": "Use the language's deterministic PRNG initialized with the given seed. Document any PRNG-specific behavior if comparing across languages.", "sampleInput": "42", "sampleOutput": "37 1000", "note": "This problem practices the workflow of population, fitness, selection, crossover, mutation, and elitism rather than a unique cross-language output. For strict judging, the organizer should define the exact PRNG algorithm."}];
